CREATE TABLE legui_private.shoppers(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL UNIQUE CHECK(email=lower(btrim(email)) AND length(email)<=254),
 name text NOT NULL CHECK(length(name) BETWEEN 2 AND 100),password_hash text NOT NULL,active boolean NOT NULL DEFAULT true,email_verified boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE legui_private.shopper_sessions(digest text PRIMARY KEY CHECK(digest ~ '^[a-f0-9]{64}$'),shopper_id uuid NOT NULL REFERENCES legui_private.shoppers(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '7 days',revoked_at timestamptz);
CREATE INDEX shopper_sessions_identity ON legui_private.shopper_sessions(shopper_id);
CREATE TABLE legui_private.shopper_actions(digest text PRIMARY KEY,shopper_id uuid NOT NULL REFERENCES legui_private.shoppers(id),purpose text NOT NULL CHECK(purpose IN ('verify','reset')),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '1 hour',used_at timestamptz);
CREATE TABLE legui_private.shopper_orders(order_id uuid PRIMARY KEY REFERENCES public.orders(id),shopper_id uuid NOT NULL REFERENCES legui_private.shoppers(id),linked_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX shopper_orders_history ON legui_private.shopper_orders(shopper_id,linked_at DESC);
CREATE TRIGGER shopper_orders_immutable BEFORE UPDATE OR DELETE ON legui_private.shopper_orders FOR EACH ROW EXECUTE FUNCTION legui_private.reject_history_change();
CREATE TABLE legui_private.shopper_preferences(shopper_id uuid NOT NULL REFERENCES legui_private.shoppers(id),brand_id uuid NOT NULL REFERENCES public.brands(id),newsletter boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(shopper_id,brand_id));
CREATE TABLE legui_private.shopper_preference_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),shopper_id uuid NOT NULL REFERENCES legui_private.shoppers(id),brand_id uuid NOT NULL REFERENCES public.brands(id),newsletter boolean NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TRIGGER shopper_preference_events_immutable BEFORE UPDATE OR DELETE ON legui_private.shopper_preference_events FOR EACH ROW EXECUTE FUNCTION legui_private.reject_history_change();
CREATE TABLE legui_private.shopper_coupons(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),brand_id uuid NOT NULL REFERENCES public.brands(id),tenant_id uuid,shopper_id uuid REFERENCES legui_private.shoppers(id),
 code text NOT NULL CHECK(code ~ '^[A-Z0-9_-]{3,32}$'),percent integer NOT NULL CHECK(percent BETWEEN 1 AND 50),minimum numeric(12,2) NOT NULL DEFAULT 0 CHECK(minimum>=0 AND minimum<>'NaN'),max_uses integer NOT NULL CHECK(max_uses BETWEEN 1 AND 100000),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),expires_at timestamptz NOT NULL,CHECK(expires_at>created_at),UNIQUE(brand_id,code),FOREIGN KEY(brand_id,tenant_id) REFERENCES public.tenants(brand_id,id));
CREATE TABLE legui_private.shopper_coupon_uses(coupon_id uuid NOT NULL REFERENCES legui_private.shopper_coupons(id),shopper_id uuid NOT NULL REFERENCES legui_private.shoppers(id),order_id uuid NOT NULL UNIQUE REFERENCES public.orders(id),discount numeric(12,2) NOT NULL CHECK(discount>0 AND discount<>'NaN'),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(coupon_id,shopper_id));
CREATE TRIGGER shopper_coupon_uses_immutable BEFORE UPDATE OR DELETE ON legui_private.shopper_coupon_uses FOR EACH ROW EXECUTE FUNCTION legui_private.reject_history_change();
DO $$DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['shoppers','shopper_sessions','shopper_actions','shopper_orders','shopper_preferences','shopper_preference_events','shopper_coupons','shopper_coupon_uses'] LOOP EXECUTE format('ALTER TABLE legui_private.%I ENABLE ROW LEVEL SECURITY',n);EXECUTE format('REVOKE ALL ON legui_private.%I FROM PUBLIC,anon,authenticated,service_role',n);END LOOP;END$$;
